"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["2710"],{549(e,t,n){n.r(t),n.d(t,{metadata:()=>a,default:()=>d,frontMatter:()=>s,contentTitle:()=>r,toc:()=>c,assets:()=>l});var a=JSON.parse('{"id":"reference/monitor","title":"Monitor","description":"connectivity \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/monitor.md","sourceDirName":"reference","slug":"/reference/monitor","permalink":"/personal-av-docs/docs/reference/monitor","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/monitor.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"Monitor","sidebar_label":"Monitor","sidebar_position":99,"edition":"connectivity","source":"https://doc.airvantage.net/connectivity/reference/monitor","format":"md"}}'),i=n(4848),o=n(8453);let s={title:"Monitor",sidebar_label:"Monitor",sidebar_position:99,edition:"connectivity",source:"https://doc.airvantage.net/connectivity/reference/monitor",format:"md"},r,l={},c=[];function h(e){let t={a:"a",p:"p",strong:"strong",...(0,o.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)(t.p,{children:[":::note Edition\n",(0,i.jsx)(t.strong,{children:"connectivity"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,i.jsx)(t.a,{href:"https://doc.airvantage.net/connectivity/reference/monitor",children:"Original page"}),".\n:::"]}),"\n",(0,i.jsx)(t.p,{children:"Monitor\nConfigure\nAPI, Connectors & Other Services\nWeb Services API\nCloud Connectors\nCloud Connectors Format\nUSSD Gateway\nMore\nProduct page\nSearching...\nMatching results\nMonitor\nMonitor\nhelps you manage your fleet of SIMs/Systems deployed on the field.\nIt provides access to all the systems of the company along with their status, provisioning information, usage history, and lifecycle management capabilities.\nThis page is also customizable to present the information that is most important to you.\nInitializing Table Of Contents...\nDashboard\nConfigurable interactive dashboard\nThe dashboard is accessible by clicking on the Sierra Wireless logo in the top banner.\nThe Dashboard is user configurable so you can get a quick look at the information that is most important. Status distribution, alerts or fleet usage consumption for example.\nThe widgets are interactive so by clicking on a pie chart segment you will be taken directly to a list of corresponding SIMs.\nSee\nDashboard section\nfor more information.\nThe\nMonitor\nactivity is divided in three sections:\nThe\nSystems\nsection. It provides access to all systems along with their status, provisioning information, usage history, and life cycle management.\nThe\nAlerts\nsection shows all the systems currently in alert state aside with the alert rule(s) responsible for the system being in alert.\nAn overview of all\nOperations\nlaunched on systems (see\nHow to use Operations?\nfor more information)\nList View\nThe\nSystems\nsection shows all the Systems in your company along with their state, provisioning and usage information. We call it\n\u201CSystems\u201D\nbecause you can specify the Name, IMEI and Serial Number of the device associated to the SIM, therefore creating and managing a fleet of IoT systems.\nThe columns displayed can be organized, resized and configured to show the parameters you need:\nLifecycle\nThe state defines whether the subscriptions are activated for usage or not and if the monthly charges are due or not (often used in delivery phase).\nEach system state can be described as follows:\nInventory\nThis is the state in which the SIMs are shipped to the customer. In this state, it is not possible to use the SIMs. Monthly charges are also not due.\nTest Ready\nTest-ready-mode can be used to optimize and simplify testing and deployment processes. Test-ready-mode means that a SIM is allowed to be tested during a defined test period and with a limited volume of traffic, without being charged for the monthly fees. Note that you are still accountable of usage fees while in test ready state. Whichever of the time criteria or traffic threshold is met will automatically result in the system status being changed to Active and normal charges will be applied.\nTo benefit of test ready mode, you simply need to activate the system on a Test-Ready-Mode compatible offer. Upon activation, the system will be displayed in Test Ready state. At the end of the test ready period, the system will automatically switch to Active state, and start being charged based on the offer it has been activated on.\nActive\nThe SIM cards are Active from the date of activation. The offer will be selected as part of the activation.\nWhile Active, the SIM cards are charged for the monthly subscription fees and are able to generate traffic corresponding to the activated services and options.\nSuspended\nA SIM card in Suspended state cannot generate any traffic. Depending on your contract, the monthly subscription fee may still be running while Suspended.\nRetired\nA \u201CRetired\u201D SIM card cannot be used nor re-activated again. It is blocked for usage, meaning that usage of any bearer service is not possible and will not be possible with this SIM again.\nCreate connectivity management operations\nTo trig a lifecycle change or provisioning change on one or multiple systems, you will create an operation. The different operation that can be triggered are:\nReview Details\nDrill down to the detailed view of one system.\nChange Label\nAdd or remove labels.\nActivate\nActivate one or multiple systems/SIMs on a selected offer to enable traffic.\nChange Offer\nChange the offer for one or multiple SIMs. There is no restriction in the target offer, it can be any offer of your contract. If the target offer has a different roaming configuration, the change offer is followed by a detach from network (Cancel Location)\nChange Provisioning Options\nChange provisioning options (permitted services and roaming zone templates) for one or multiple SIMs/Systems. Available options depend on the selected offer. Changing roaming configuration is followed by a detach from network (Cancel Location)\nSuspend\nSuspend one or multiple SIMs/Systems. A suspended SIM will not be able to connect to the network, and therefore will be unable to generate usages.\nRestore\nRestore one or multiple SIMs/Systems. The SIM will be able to reconnect to the network and generate usages.\nTerminate\nTerminate one or multiple SIMs/Systems. A terminated SIM will not be usable any more. The Terminate action cannot be reverted.\nSwap SIM\nSwap out the selected SIM for a replacement. This is to be used for example when a SIM card is stolen or damaged. Only the ICCID will be changed, to that of the new SIM, while keeping all identifiers related to the subscription (MSISDN, Static IP, offer, provisioning options, etc.). The ICCID of the stolen/damaged SIM will be terminated as a consequence of the Swap.\nTransfer\nTransfer one or several systems to a partner, for example to a subaccount. The usages consumed within the original company will remain attached to the original company and therefore will not be displayed in the target company.\nSend SMS\nSend a text SMS to one or multiple systems. For SW Advanced, SW Essentials and 3rd party SIMs this requires a SMS gateway to be configured in your company. See\nHow to configure an SMS account?\nfor help. For Enhanced Carrier Connectivity SIMs, this is straightforward. The Send SMS operation finishing in success means that the SMS has been received by the device; with the exception of SMPP-based SMS accounts, for which it means received by the SMS-C.\nExport last data\nExport in a .csv file a copy of the information available in AirVantage for multiple systems.\nEdit\nUpdate the system name, IMEI and/or Serial Number of the device associated to the SIM in bulk\nDepending on the current state of your system, only the actions that can be triggered in that state will be available.\nThere are no restrictions on the number of suspend or change offer operations that can be triggered within a month besides the rules imposed by the carriers. Meaning that:\nSW Advanced, SW Essentials: no restriction\nVerizon: maximum 2 suspend operations per year\nManage large deployments\nFinding a SIM or group of SIMs of interest is easy using filters. These can be applied for single or multiple variables: filter on state + activation date.\nLabels gives a powerful way to add flexibility in identifying systems.\nThey can be used for geographic regions, fleet owner, type of device in which the SIM is inserted, or any other identifier that you would like to apply and use as a search term in the future. We also apply a label with the order ID so that you can easily select all SIMs from a specific order.\nSystems can have an unlimited number of labels.\nThe result of the filtered list is displayed in multiple pages if needed. You can select all the list with the check box displayed at the top left of the list.\nSee simple example below:\nThe filtered list can be saved in a group of systems using a label:\nSelect all\nSelect action Change labels\nAdd the label for the new group\nOr directly used to perform one of the connectivity management operation.\nDetailed View\nMost recent activity and configuration of the system is available from the  details screen.\nThis page provides access into the configuration, provisioning, usage consumption trends and detailed records.\nThe details of a given system are accessed from the Systems list view clicking on the\nDetails icon\nin the actions toolbar after selecting a system or directly in the grid by clicking on the line of the system of choice.\nBill shock management\nMonitor activity proposes different capabilities to track usage consumption per system and helps you prevent bill shock.\nUsage consumption and status\nThe system list gives you a vision of your fleet along with some of their key usage information:\nThe amount of data consumed in the current billing month\nThe offer that has been selected for each system at activation\nThe percentage of the consumed offer bundle for each SIM with a color coded status.\nNote that the usage information displayed in AirVantage in bill shock related functionalities is the invoiced usage data i.e. taking into account billing increments applied to each data session.\nSorting the grid per usage consumption enables you to spot your most consuming devices within the fleet.\nIn addition to the grid, the\nAirTime Usage status\nwidget tracks usage consumed against the bundle offer indicating with a color coded status:\nWhich systems are operating within their monthly allotted usage within their bundle (within plan)\nWhich systems are within 80% of the allotted bundle usage (nearing plan)\nWhich systems have exceeded the allotted bundle usage (exceeding plan)\nThis widget is especially helpful in identifying systems that may be experiencing an unplanned usage surge. In case you are using a Pay-per-use model, the usage status will be undefined.\nAlerts\nAirVantage supports 2 types of alert:\nstateful alerts\nhave a duration. These alert rules have a status that is raised as long as the conditions are met, and is cleared when the conditions are not met anymore (example: alert rule on communication status error, or on usage consumption over specific threshold). They contribute to the system\u2019s alert state.\nevents\n(or stateless alerts) are one shot non lasting alerts. They are usually generated by rules using the CHANGE or EXISTS operators (example: alert rule on system state changes). Events or stateless alerts are generated each time the rules conditions are met. Due to their ephemeral characteristc, they don\u2019t impact the system\u2019s alert state.\nIdentify systems in alert\nEach system has got an alert state: a system can either be\nin alert\nor\nnot in alert\n\u2018-\u2019.\nA system in alert has at least one alert rule for which an alert is currently raised on the system. As soon as the previous alert criteria is no longer met, meaning that the system goes back to expected behavior, its alert state will go back to \u2018not in alert\u2019.\nIf a system is in alert state due to several alerts being raised at the same time, its alert state will be cleared only once all rule violations have been fixed.\nYou can easily identify systems in alert in the grid of systems using the column \u201Calert state\u201D and \u201Calert state change date\u201D.\nAlert state is showing whether a system is currently in alert or not. A system in alert can be in alert due to one or more alert rules being fulfilled.\nAlert state change date informs you when the system became in alert, or back to normal. This column is not displayed by default, but can be added.\nYou can use the filtering capabilities with the alert state criteria to display only systems that have at least one alert currently raised.\nCheck Alerts\nThe loudspeaker with a red counter on the top banner displays the number of currently raised alarms on your fleet, with one different entry per system or offer and per alert rule. It appears as soon as you are logged in AirVantage.\nThe\nMonitor > Current Alerts\nsection is displaying all alerts currently raised on your systems and offers. Consequently, only stateful alerts currently raised are displayed in this screen. The list can be filtered by Alert rule name, type of target (system or offer) and also on the specific system or offer.\nAlert rules are created in the\nConfigure activity: Alert section\n.\nFinally you can click on an alert to show the details:\nrelated to the rules\nrelated to the conditions which raised the alert.\nAnalyze Alerts\nThe\nMonitor > Alert History\nsection is displaying the alert history of your systems (events and for stateful alerts, when they have been raised and cleared). The list can be filtered by Alert rule name, target system, target offer, or a given period of time. In a single click, you can access to the rule, the system details, the systems with targeted offer, and the system\u2019s timeline to analyze the system(s) behavior.\nAlert rules are created in the\nConfigure activity: Alert section\n.\nConnectivity Diagnosis\nIn case you need a sharp analysis on one SIM or facing some issues with your connectivity, AirVantage provides some functionalities for doing a deeper dive and diagnose your wireless connection.\nView SIM usage history\nA new widget is available in the\nMonitor> System details\nto pinpoint the latest usages consumed on the selected SIM. The widget shows the type of usage along with the date at which the usage occured and the additional information related to the usage (duration, amount of data consumed, peer phone number depending on type of usage, visited network). If a session is still on-going it will be displayed as in progress.\nTo view the full list of usages you need to click on the\nAll>>\nlink at the bottom of the widget, or you can also access it by clicking on the\nUsage History\nbutton in the top banner. In this view, the usages displayed are the raw usage consumption i.e without the billing increments.\nThe Usage History displays all usages consumed on the selected SIM (display is limited to 100 records at a time). You can drill down to a specific date by using the filters on top.\nFor data usages:\ndata session START and STOP events are now displayed in usage history and timeline in near real time (usually in a matter of seconds)\ndata session are updated every 15 minutes after the start of the session to provide consumption updates (INTERIM UPDATES).\nFor VOICE, SMS, USSD, usage history is updated every 15 minutes.\nTimeline\nThe timeline page presents a chronological list view of events in the device life, and can thus provide insight into an issue related to an event:\nOperations (commands, \u2026) & updates (system edition on AirVantage) applied on the system\nAlerts issued\nUsages (start & end connectivity session, \u2026)\nThe filtering mechanism limits display to only the relevant information. You can also browse the timeline.\nDiagnostics tool\nIn case you are not able to establish a communication, suspecting something wrong with the connectivity or want more details about real time status of one device, the diagnose capability helps you to understand what is going on and to troubleshoot the service.\nThe diagnose is a 3 step operation that can be triggered from\nSystem>Details\n:\nSIM state\n: checks whether the state of your SIM is currently in a correct state to perform traffic. Aside of the SIM state, we will also display the options that are active on your SIM to ease the verification.\nVoice status\n: checks the attachment status for voice services. This step includes a real-time query of the visited network to confirm or not whether the device reachability for voice service. It takes around a minute. To be noted that both reachability and location information are retreived from the 2G/3G network only.\nData status\n: checks the attachment status for data services and real time  session information such as visited network, allocated IP address, APN, the RAT on which the device is attached, and data traffic since beginning of session.\nEach step can result in one of the following statuses:\nSuccess\n: Configuration and/or connectivity behavior are normal.\nWarning\n: Connectivity has already been working as expected on this device but is currently temporary interrupted (device being off, or out of coverage, etc\u2026)\nError\n: Device configuration and connectivity are not working and may have never been working before.\nWhen an error is detected, the Diagnose tool will suggest possible causes and ways to troubleshoot the issue.\nNote that Diagnose takes 1 to 2 minutes to complete.\nDetach the SIM from the network\nThe detach can be used if you suspect an issue with the wireless service: for instance, the diagnose displays that a session is on-going, but you are not able to effectively transmit data, or the diagnose shows that your device is reachable but you are not able to send SMS.\nClicking on \u2018Detach\u2019\nin the Voice Status pane trigs a detach procedure from the network side, leading to the device restarting an attach procedure and also a data session establishment from the beginning. To be noted that in most cases the device will register to the same network if this network is available.\nIf you use a SW Advanced SIM you can also use the \u2018Detach Data only\u2019 functionality in the Data Status pane. In that case, the SIM will automatically detect the loss of data service and the device will register to another network.\nHow-Tos\nThis section provides you with helpful procedures for common tasks.\nHow To Update Systems to Add Unique Labels\nHow to activate a SIM/System with a custom static IP Address?\nHow to activate an Enhanced Carrier Connectivity Verizon SIM?\nHow to change provisioning options?\nHow to configure Smart Connectivity for LPWA use cases?\nHow to edit csv files?\nHow to export SIM parameter data\nHow to launch a bulk activation?\nHow to use Operations?"})]})}function d(e={}){let{wrapper:t}={...(0,o.R)(),...e.components};return t?(0,i.jsx)(t,{...e,children:(0,i.jsx)(h,{...e})}):h(e)}},8453(e,t,n){n.d(t,{R:()=>s,x:()=>r});var a=n(6540);let i={},o=a.createContext(i);function s(e){let t=a.useContext(o);return a.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:s(e.components),a.createElement(o.Provider,{value:t},e.children)}}}]);